95	static int write_seed_file(const char *path, const char *body)
96	{
97	  size_t len = strlen(body);
98	  bool same = false;
99	  struct stat st;
100	  int fd;
101	
102	  /* Refresh in place when eMMC already holds an older seed text, so
103	   * firmware-side wording changes land on previously provisioned boards. */
104	
105	  fd = open(path, O_RDONLY);
106	  if (fd >= 0)
107	    {
108	      if (fstat(fd, &st) == 0 && st.st_size == (off_t)len)
109	        {
110	          char chunk[128];
111	          size_t off;
112	
113	          same = true;
114	          for (off = 0; off < len && same; off += sizeof(chunk))
115	            {
116	              size_t want = len - off;
117	              ssize_t got;
118	
119	              if (want > sizeof(chunk))
120	                {
121	                  want = sizeof(chunk);
122	                }
123	
124	              got = read(fd, chunk, want);
125	              if (got != (ssize_t)want ||
126	                  memcmp(chunk, body + off, want) != 0)
127	                {
128	                  same = false;
129	                }
130	            }
131	        }
132	
133	      close(fd);
134	      if (same)
135	        {
136	          return 0;
137	        }
138	    }
139	
140	  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
141	  if (fd < 0)
142	    {
143	      return -errno;
144	    }
145	
146	  if (write(fd, body, len) != (ssize_t)len)
147	    {
148	      close(fd);
149	      return -EIO;
150	    }
151	
152	  close(fd);
153	  return 0;
154	}
