252	/* Signature of the alarm set: ids + severities (order). Values, durations
253	 * and ack/mute flags change every tick — refreshed in place, not in sig. */
254	static void build_sig(char * out, size_t cap, const vg_alarm_t * list, int n)
255	{
256	    size_t used = 0;
257	    int i, w;
258	
259	    out[0] = '\0';
260	    for(i = 0; i < n && used + 1 < cap; i++) {
261	        w = lv_snprintf(out + used, cap - used, "%s%c,",
262	                        list[i].sensor_id, (char)('0' + (int)list[i].severity));
263	        if(w < 0) break;
264	        used += (size_t)w;
265	    }
266	}
