349	static void set_row_texts(int idx, const vg_alarm_t * a)
350	{
351	    const vg_sensor_t * s = vg_model_get_sensor(a->sensor_id);
352	    const bool selected = (strcmp(s_alarm_ui.sel_id, a->sensor_id) == 0);
353	    char buf[96];
354	    char v1[16];
355	
356	    if(s_alarm_ui.row_name[idx]) {
357	        lv_label_set_text(s_alarm_ui.row_name[idx], s ? s->name : a->sensor_id);
358	        /* Selection cue beyond the subtle bg: accent-colored point name */
359	        lv_obj_set_style_text_color(s_alarm_ui.row_name[idx],
360	                                    selected ? vg_color_accent()
361	                                             : (s && s->online ? vg_color_text()
362	                                                               : vg_color_muted()), 0);
363	    }
364	    if(s_alarm_ui.row_chip[idx]) {
365	        vg_status_chip_set(s_alarm_ui.row_chip[idx],
366	                           vg_severity_label_zh(a->severity), a->severity);
367	    }
368	    if(s_alarm_ui.row_obj[idx]) {
369	        lv_obj_set_style_border_color(s_alarm_ui.row_obj[idx],
370	                                      vg_color_severity(a->severity), 0);
371	        lv_obj_set_style_bg_color(s_alarm_ui.row_obj[idx],
372	                                  selected ? lv_color_hex(ALARM_ROW_SELECTED_BG)
373	                                           : vg_color_surface(), 0);
374	    }
375	    if(s_alarm_ui.row_sum[idx]) {
376	        if(a->severity == VG_SEV_OFFLINE || s == NULL) {
377	            lv_snprintf(buf, sizeof(buf), "通信离线 · 持续 %ds", a->duration_sec);
378	        }
379	        else {
380	            fmt_f1(v1, sizeof(v1), a->value);
381	            {
382	                char v2[16];
383	                size_t len;
384	                fmt_f1(v2, sizeof(v2), a->threshold);
385	                len = (size_t)lv_snprintf(buf, sizeof(buf), "当前 %s%s · 阈值 %s%s · 持续 %ds",
386	                                          v1, s->unit, v2, s->unit, a->duration_sec);
387	                if(a->acked && len < sizeof(buf)) {
388	                    lv_snprintf(buf + len, sizeof(buf) - len, " · 已处理");
389	                }
390	                else if(a->muted && len < sizeof(buf)) {
391	                    lv_snprintf(buf + len, sizeof(buf) - len, " · 已静音");
392	                }
393	            }
394	        }
395	        lv_label_set_text(s_alarm_ui.row_sum[idx], buf);
396	    }
397	    if(s_alarm_ui.row_ack[idx]) {
398	        if(a->acked) lv_obj_add_state(s_alarm_ui.row_ack[idx], LV_STATE_DISABLED);
399	        else lv_obj_remove_state(s_alarm_ui.row_ack[idx], LV_STATE_DISABLED);
400	    }
401	    if(s_alarm_ui.row_mute[idx]) {
402	        if(a->muted) lv_obj_add_state(s_alarm_ui.row_mute[idx], LV_STATE_DISABLED);
403	        else lv_obj_remove_state(s_alarm_ui.row_mute[idx], LV_STATE_DISABLED);
404	    }
405	}
