407	/* Detail section bound to the selected alarm (NULL = empty state) */
408	static void render_detail(const vg_alarm_t * a)
409	{
410	    const vg_sensor_t * as = NULL;
411	    char buf[160];
412	    char a1[16];
413	    int i;
414	    int start;
415	    int npts;
416	
417	    if(a == NULL) {
418	        for(i = 0; i < 6; i++) {
419	            vg_metric_row_set_value(s_alarm_ui.metric_rows[i], "--");
420	        }
421	        vg_metric_row_set_value(s_alarm_ui.metric_rows[4], "--");
422	        lv_label_set_text(s_alarm_ui.hist_lab, "历史: --");
423	        set_ai_text("【规则摘要】当前无活动告警。");
424	        return;
425	    }
426	
427	    if(a->sensor_id[0] != '\0') {
428	        as = vg_model_get_sensor(a->sensor_id);
429	    }
430	
431	    vg_metric_row_set_value(s_alarm_ui.metric_rows[0],
432	                            a->severity == VG_SEV_OFFLINE ? "通信离线" : "阈值越限");
433	    if(a->severity == VG_SEV_OFFLINE || as == NULL) {
434	        vg_metric_row_set_value(s_alarm_ui.metric_rows[1], "--");
435	        vg_metric_row_set_value(s_alarm_ui.metric_rows[2], "--");
436	    }
437	    else {
438	        fmt_f1(a1, sizeof(a1), a->value);
439	        lv_snprintf(buf, sizeof(buf), "%s %s", a1, as->unit);
440	        vg_metric_row_set_value(s_alarm_ui.metric_rows[1], buf);
441	
442	        fmt_f1(a1, sizeof(a1), a->threshold);
443	        lv_snprintf(buf, sizeof(buf), "%s %s", a1, as->unit);
444	        vg_metric_row_set_value(s_alarm_ui.metric_rows[2], buf);
445	    }
446	
447	    lv_snprintf(buf, sizeof(buf), "%d s", a->duration_sec);
448	    vg_metric_row_set_value(s_alarm_ui.metric_rows[3], buf);
449	    vg_metric_row_set_value(s_alarm_ui.metric_rows[4], as ? as->name : "--");
450	    vg_metric_row_set_value(s_alarm_ui.metric_rows[5],
451	                            a->acked ? "已处理" : (a->muted ? "已静音" : "活动中"));
452	
453	    npts = 0;
454	    buf[0] = '\0';
455	    if(as != NULL) {
456	        npts = 8;
457	        if(as->history_len < npts) npts = as->history_len;
458	        start = (int)as->history_len - npts;
459	        if(start < 0) start = 0;
460	        for(i = 0; i < npts; i++) {
461	            char p[12];
462	            fmt_f1(p, sizeof(p), as->history[start + i]);
463	            if(i == 0) {
464	                lv_snprintf(buf, sizeof(buf), "%s", p);
465	            }
466	            else {
467	                size_t len = strlen(buf);
468	                lv_snprintf(buf + len, sizeof(buf) - len, " %s", p);
469	            }
470	        }
471	    }
472	    if(npts == 0) {
473	        lv_label_set_text(s_alarm_ui.hist_lab, "历史: --");
474	    }
475	    else {
476	        char full[128];
477	        lv_snprintf(full, sizeof(full), "历史: %s", buf);
478	        lv_label_set_text(s_alarm_ui.hist_lab, full);
479	    }
480	
481	    if(as != NULL && a->severity != VG_SEV_OFFLINE) {
482	        lv_snprintf(buf, sizeof(buf),
483	                    "【规则摘要】%s 当前 %.1f%s，阈值 %.1f%s，已持续 %d 秒。"
484	                    "判定来自点表 cmp/阈值，本地规则引擎。",
485	                    as->name, (double)a->value, as->unit,
486	                    (double)a->threshold, as->unit, a->duration_sec);
487	    }
488	    else if(a->severity == VG_SEV_OFFLINE) {
489	        lv_snprintf(buf, sizeof(buf),
490	                    "【规则摘要】滑窗读失败达阈值，离线已持续 %d 秒。",
491	                    a->duration_sec);
492	    }
493	    else {
494	        lv_snprintf(buf, sizeof(buf),
495	                    "【规则摘要】有活动告警，但本地尚无该点读数。");
496	    }
497	    set_ai_text(buf);
498	}
