500	static void refresh_alarm(void * user)
501	{
502	    const vg_alarm_t * sel = NULL;
503	    vg_alarm_t list[ALARM_LIST_MAX];
504	    char newsig[sizeof(s_alarm_ui.sig)];
505	    char buf[32];
506	    uint16_t total;
507	    int n;
508	    int i;
509	    LV_UNUSED(user);
510	    if(vg_nav_current() != VG_PAGE_ALARM) return;
511	    if(s_alarm_ui.root == NULL || !lv_obj_is_valid(s_alarm_ui.root)) return;
512	
513	    total = vg_model_active_alarm_count();
514	    n = vg_model_collect_alarms(list, ALARM_LIST_MAX);
515	
516	    /* Head: real total count (list caps at ALARM_LIST_MAX) + top severity */
517	    if(total > 0 && n > 0) {
518	        lv_snprintf(buf, sizeof(buf), "活动告警 %u 个", (unsigned)total);
519	        lv_label_set_text(s_alarm_ui.title, buf);
520	        vg_status_chip_set(s_alarm_ui.chip,
521	                           vg_severity_label_zh(list[0].severity), list[0].severity);
522	    }
523	    else {
524	        lv_label_set_text(s_alarm_ui.title, "无活动告警");
525	        vg_status_chip_set(s_alarm_ui.chip, "正常", VG_SEV_OK);
526	    }
527	
528	    if(total == 0) s_alarm_ui.sel_id[0] = '\0';
529	
530	    /* Rebuild rows only when the alarm set changed; refresh texts always */
531	    if(s_alarm_ui.list == NULL || !lv_obj_is_valid(s_alarm_ui.list)) return;
532	    build_sig(newsig, sizeof(newsig), list, n);
533	    if(strcmp(newsig, s_alarm_ui.sig) != 0) {
534	        if(alarm_gesture_active()) {
535	            /* Keep geometry; apply once when the gesture ends. */
536	            strncpy(s_alarm_ui.pending_sig, newsig, sizeof(s_alarm_ui.pending_sig) - 1);
537	            s_alarm_ui.pending_sig[sizeof(s_alarm_ui.pending_sig) - 1] = '\0';
538	            s_alarm_ui.struct_pending = true;
539	        }
540	        else {
541	            strncpy(s_alarm_ui.sig, newsig, sizeof(s_alarm_ui.sig) - 1);
542	            s_alarm_ui.sig[sizeof(s_alarm_ui.sig) - 1] = '\0';
543	            rebuild_rows(list, n);
544	            s_alarm_ui.struct_pending = false;
545	        }
546	    }
547	
548	    if(!s_alarm_ui.struct_pending) {
549	        for(i = 0; i < n && i < s_alarm_ui.row_n; i++) {
550	            set_row_texts(i, &list[i]);
551	            if(sel == NULL && s_alarm_ui.sel_id[0] != '\0' &&
552	               strcmp(s_alarm_ui.sel_id, list[i].sensor_id) == 0) {
553	                sel = &list[i];
554	            }
555	        }
556	        if(sel == NULL && n > 0) {
557	            strncpy(s_alarm_ui.sel_id, list[0].sensor_id, sizeof(s_alarm_ui.sel_id) - 1);
558	            s_alarm_ui.sel_id[sizeof(s_alarm_ui.sel_id) - 1] = '\0';
559	            sel = &list[0];
560	            if(s_alarm_ui.row_obj[0] && lv_obj_is_valid(s_alarm_ui.row_obj[0])) {
561	                set_row_texts(0, &list[0]);
562	            }
563	        }
564	    }
565	    else {
566	        /* Structure frozen: still refresh same-ID rows in place; skip reorder. */
567	        for(i = 0; i < s_alarm_ui.row_n; i++) {
568	            int j;
569	            for(j = 0; j < n; j++) {
570	                if(strcmp(s_alarm_ui.row_id[i], list[j].sensor_id) == 0) {
571	                    set_row_texts(i, &list[j]);
572	                    if(sel == NULL && s_alarm_ui.sel_id[0] != '\0' &&
573	                       strcmp(s_alarm_ui.sel_id, list[j].sensor_id) == 0) {
574	                        sel = &list[j];
575	                    }
576	                    break;
577	                }
578	            }
579	        }
580	    }
581	
582	    render_detail(sel);
583	}
