static void strip_markdown(char *s)
{
  char *r = s;
  char *w = s;

  while(*r != '\0') {
    char *e = strchr(r, '\n');
    const char *line_end = (e != NULL) ? e : r + strlen(r);
    const char *p = r;
    bool fence_line;

    while(p < line_end && *p == ' ') {
      p++;
    }
    fence_line = (line_end - p >= 3 &&
                  p[0] == '`' && p[1] == '`' && p[2] == '`');
    if(!fence_line) {
      bool table_sep = false;

      while(p < line_end && *p == '#') {
        p++;
      }
      while(p < line_end && *p == ' ') {
        p++;
      }
      if(p < line_end && *p == '|') {
        const char *q;

        table_sep = true;
        for(q = p; q < line_end; q++) {
          if(*q != '|' && *q != '-' && *q != ':' && *q != ' ' &&
             *q != '\t') {
            table_sep = false;
            break;
          }
        }
      }
      if(!table_sep) {
        for(; p < line_end; p++) {
          if(*p == '*' || *p == '`') {
            continue;
          }
          *w++ = (*p == '|') ? ' ' : *p;
        }
      }
    }

    if(e != NULL) {
      *w++ = '\n';
      r = e + 1;
    }
    else {
      r = line_end;
    }
  }
  *w = '\0';
}

