static void sb_printf(sb_t *sb, const char *fmt, ...)
{
  va_list ap;
  int w;

  if (sb->over || sb->cap == 0 || sb->len >= sb->cap - 1) {
      sb->over = true;
      return;
  }

  va_start(ap, fmt);
  w = vsnprintf(sb->buf + sb->len, sb->cap - sb->len, fmt, ap);
  va_end(ap);

  if (w < 0) { sb->over = true; return; }

