/****************************************************************************
 * app/velaguard/vg_agent_round.h
 *
 * Board-driven agent rounds.
 *
 * The HMI build does not run ReAct from the heartbeat (heartbeat_send() is
 * gated under CONFIG_VG_HMI) and cron is skipped, so the board itself has to
 * ask the agent for the two proactive flows: explaining the active alarms and
 * writing the daily report.  Both go through this one door so that only a
 * single round is ever outstanding, and so the UI thread never waits.
 *
 * Usage from the board backend:
 *   vg_agent_round_tick()   every file-worker tick, drives submit + watchdog
 *   vg_agent_round_queue()  hand over a request built by vg_ai_contract
 *   vg_agent_round_state()  poll from the UI side, then read the artifact
 ****************************************************************************/

#ifndef __APP_VELAGUARD_VG_AGENT_ROUND_H
#define __APP_VELAGUARD_VG_AGENT_ROUND_H

#include <stdbool.h>
#include <stdint.h>

enum vg_agent_round_state
{
  VG_AGENT_ROUND_IDLE = 0,  /* nothing outstanding; result (if any) consumed */
  VG_AGENT_ROUND_QUEUED,    /* accepted, not yet handed to the agent bus */
  VG_AGENT_ROUND_RUNNING,   /* pushed; waiting for the agent to answer */
  VG_AGENT_ROUND_DONE,      /* the agent answered; read the artifact for truth */
  VG_AGENT_ROUND_ERROR      /* could not be delivered, or the round ran long */
};

/* Total budget for one round, in milliseconds.  Measured rounds on this board
 * run 100-190 s wall clock (six ReAct iterations, ~105 s inside the LLM), so
 * this is deliberately far above the 120 s per-call watchdog.  Expiry only
 * means "stop waiting": the artifact carries boot and req, so a late answer
 * is rejected by vg_ai_advice_parse() rather than mistaken for a later round. */

#define VG_AGENT_ROUND_TIMEOUT_MS       300000u

/* How long a queued request may wait for the agent bus to come up. */

#define VG_AGENT_ROUND_QUEUE_TIMEOUT_MS  20000u

/* Opens the local agent client if it is not open yet.  Returns 0 when the
 * client is ready, -ENODEV while the agent is still starting (retry later).
 * Safe to call repeatedly. */

int vg_agent_round_init(void);

/* Hand over one request.  Returns 0 on success, -EBUSY when a round is
 * already queued or running, -EINVAL on an empty request, -E2BIG when the
 * text does not fit the internal buffer.  The text is copied. */

int vg_agent_round_queue(const char *text);

/* Drive submission and the watchdog.  Call from the file worker thread. */

void vg_agent_round_tick(void);

/* State and bookkeeping for the consumer side. */

enum vg_agent_round_state vg_agent_round_state(void);
bool                    vg_agent_round_busy(void);

/* Bumped every time a round finishes with a reply, so a consumer can tell a
 * fresh result from one it already handled. */

uint32_t vg_agent_round_generation(void);

/* Returns DONE or ERROR to IDLE so the next round may be queued.  A DONE
 * result must be consumed (the artifact read and validated) before this. */

void vg_agent_round_clear(void);

/* Last reply text, truncated for diagnostics (NSH readback, logs). */

const char *vg_agent_round_last_reply(void);

/* Monotonic milliseconds.  Every deadline and rate limit on this path uses
 * this base: the wall clock jumps when vgtime syncs a minute after boot, and
 * one jump would otherwise expire every in-flight round at once. */

uint32_t vg_agent_round_now_ms(void);

#endif /* __APP_VELAGUARD_VG_AGENT_ROUND_H */

/****************************************************************************
 * app/velaguard/vg_agent_round.c
 ****************************************************************************/

#include <nuttx/config.h>

#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA

#include <errno.h>
#include <pthread.h>
#include <string.h>
#include <syslog.h>
#include <time.h>

#include <velaclaw/client.h>

#include "vg_agent_round.h"

#define TAG "vgagent"

#define VG_ROUND_REQ_MAX   1536
#define VG_ROUND_REPLY_MAX 192

static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;

static velaclaw_client_t          *g_client;
static enum vg_agent_round_state   g_state = VG_AGENT_ROUND_IDLE;
static uint32_t                    g_started_ms;
static uint32_t                    g_generation;
static bool                        g_reply_seen;
static bool                        g_reply_ok;

static char g_req[VG_ROUND_REQ_MAX];
static char g_reply[VG_ROUND_REPLY_MAX];

uint32_t vg_agent_round_now_ms(void)
{
  struct timespec ts;

  (void)clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)((uint64_t)ts.tv_sec * 1000u
                    + (uint64_t)ts.tv_nsec / 1000000u);
}

/* Runs on the agent's outbound dispatch thread, so it only records the
 * outcome and never blocks on anything but this mutex. */

static void round_reply(int status, const char *text, void *cookie)
{
  (void)cookie;

  pthread_mutex_lock(&g_lock);
  g_reply_seen = true;
  g_reply_ok = (status == 0);

  if (text != NULL)
    {
      strncpy(g_reply, text, sizeof(g_reply) - 1);
      g_reply[sizeof(g_reply) - 1] = '\0';
    }
  else
    {
      g_reply[0] = '\0';
    }

  pthread_mutex_unlock(&g_lock);
}

int vg_agent_round_init(void)
{
  int rc = 0;

  pthread_mutex_lock(&g_lock);

  if (g_client == NULL)
    {
      /* Fails while the agent's message bus is still coming up; the worker
       * retries on later ticks until VG_AGENT_ROUND_QUEUE_TIMEOUT_MS. */

      g_client = velaclaw_client_open("velaguard");
      if (g_client != NULL)
        {
          syslog(LOG_INFO, "[%s] local agent client ready\n", TAG);
        }
    }

  if (g_client == NULL)
    {
      rc = -ENODEV;
    }

  pthread_mutex_unlock(&g_lock);
  return rc;
}

int vg_agent_round_queue(const char *text)
{
  size_t len;

  if (text == NULL)
    {
      return -EINVAL;
    }

  len = strlen(text);
  if (len == 0)
    {
      return -EINVAL;
    }

  if (len >= VG_ROUND_REQ_MAX)
    {
      return -E2BIG;
    }

  pthread_mutex_lock(&g_lock);

  if (g_state == VG_AGENT_ROUND_QUEUED || g_state == VG_AGENT_ROUND_RUNNING)
    {
      pthread_mutex_unlock(&g_lock);
      return -EBUSY;
    }

  memcpy(g_req, text, len + 1);
  g_state = VG_AGENT_ROUND_QUEUED;
  g_started_ms = vg_agent_round_now_ms();
  g_reply_seen = false;
  g_reply_ok = false;
  g_reply[0] = '\0';

  pthread_mutex_unlock(&g_lock);
  return 0;
}

static void round_submit(void)
{
  /* Function-local so a 1.5 KB request never lands on the worker stack, and
   * released before the call so the reply callback can never contend with us
   * on the same lock if a build ever dispatches replies synchronously. */

  static char req[VG_ROUND_REQ_MAX];
  velaclaw_client_t *client;
  velaclaw_ask_req_t ask;
  int rc;

  pthread_mutex_lock(&g_lock);
  if (g_client == NULL)
    {
      pthread_mutex_unlock(&g_lock);

      if (vg_agent_round_init() != 0)
        {
          return;
        }

      pthread_mutex_lock(&g_lock);
    }

  client = g_client;
  memcpy(req, g_req, sizeof(req));
  pthread_mutex_unlock(&g_lock);

  ask.text = req;
  ask.timeout_ms = (int)VG_AGENT_ROUND_TIMEOUT_MS;

  rc = velaclaw_ask_async(client, &ask, round_reply, NULL);

  pthread_mutex_lock(&g_lock);
  if (rc == 0)
    {
      g_state = VG_AGENT_ROUND_RUNNING;
      g_started_ms = vg_agent_round_now_ms();
      syslog(LOG_INFO, "[%s] round submitted: %u bytes\n",
             TAG, (unsigned)strlen(req));
    }
  else
    {
      g_state = VG_AGENT_ROUND_ERROR;
      syslog(LOG_WARNING, "[%s] round submit failed: %d\n", TAG, rc);
    }

  pthread_mutex_unlock(&g_lock);
}

void vg_agent_round_tick(void)
{
  enum vg_agent_round_state st;
  uint32_t started;
  uint32_t now = vg_agent_round_now_ms();
  bool seen;
  bool ok;

  pthread_mutex_lock(&g_lock);
  st = g_state;
  started = g_started_ms;
  pthread_mutex_unlock(&g_lock);

  if (st == VG_AGENT_ROUND_QUEUED)
    {
      round_submit();

      /* A queued request that never got delivered (agent bus absent) must
       * not hold the slot forever. */

      pthread_mutex_lock(&g_lock);
      if (g_state == VG_AGENT_ROUND_QUEUED &&
          now - started >= VG_AGENT_ROUND_QUEUE_TIMEOUT_MS)
        {
          g_state = VG_AGENT_ROUND_ERROR;
          syslog(LOG_WARNING, "[%s] round never reached the agent\n", TAG);
        }
      pthread_mutex_unlock(&g_lock);
      return;
    }

  if (st != VG_AGENT_ROUND_RUNNING)
    {
      return;
    }

  pthread_mutex_lock(&g_lock);
  seen = g_reply_seen;
  ok = g_reply_ok;
  g_reply_seen = false;
  pthread_mutex_unlock(&g_lock);

  if (seen)
    {
      pthread_mutex_lock(&g_lock);
      if (ok)
        {
          g_state = VG_AGENT_ROUND_DONE;
          g_generation++;
        }
      else
        {
          g_state = VG_AGENT_ROUND_ERROR;
        }
      pthread_mutex_unlock(&g_lock);

      syslog(LOG_INFO, "[%s] round finished: %s\n",
             TAG, ok ? "reply" : "agent error");
      return;
    }

  if (now - started >= VG_AGENT_ROUND_TIMEOUT_MS)
    {
      pthread_mutex_lock(&g_lock);
      g_state = VG_AGENT_ROUND_ERROR;
      pthread_mutex_unlock(&g_lock);
      syslog(LOG_WARNING, "[%s] round timed out after %u ms\n",
             TAG, (unsigned)(now - started));
    }
}

enum vg_agent_round_state vg_agent_round_state(void)
{
  enum vg_agent_round_state st;

  pthread_mutex_lock(&g_lock);
  st = g_state;
  pthread_mutex_unlock(&g_lock);
  return st;
}

bool vg_agent_round_busy(void)
{
  enum vg_agent_round_state st = vg_agent_round_state();

  return (st == VG_AGENT_ROUND_QUEUED || st == VG_AGENT_ROUND_RUNNING);
}

uint32_t vg_agent_round_generation(void)
{
  uint32_t gen;

  pthread_mutex_lock(&g_lock);
  gen = g_generation;
  pthread_mutex_unlock(&g_lock);
  return gen;
}

void vg_agent_round_clear(void)
{
  pthread_mutex_lock(&g_lock);

  if (g_state == VG_AGENT_ROUND_DONE || g_state == VG_AGENT_ROUND_ERROR)
    {
      g_state = VG_AGENT_ROUND_IDLE;
    }

  pthread_mutex_unlock(&g_lock);
}

const char *vg_agent_round_last_reply(void)
{
  return g_reply;
}

