    return -ENOENT;
  }

  snprintf(candidate, sizeof(candidate), "%s/%s",
           CONFIG_VG_HMI_REPORT_DIR, want);

  if(access(candidate, R_OK) != 0) {
    return -errno;
  }

  if(path != NULL && path_sz > 0) {
    snprintf(path, path_sz, "%s", candidate);
  }

  return 0;
}

